import { Component, inject, OnInit, ChangeDetectorRef } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { tunisianCities } from '../../candidate/candidate-layout/tunisian-cities';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'app-profile-settings',
  standalone: true,
  imports: [FormsModule, CommonModule],
  templateUrl: './profile-settings.component.html',
  styleUrl: './profile-settings.component.css'
})
export class ProfileSettingsComponent implements OnInit {
  private cdr = inject(ChangeDetectorRef);

  profile = { company_name: '', phone: '', email: '', address: '', company_bio: '' };
  backupProfile = { company_name: '', phone: '', email: '', address: '', company_bio: '' };
  logoPreviewUrl: string | null = null;
  selectedFile: File | null = null;
  successMessage = '';
  
  // Autocomplétion Localisation
  filteredLocations: { ville: string; cite: string }[] = [];
  showLocationSuggestions: boolean = false;

  isEditMode = false; // Controle de gauche (Profil)
  isPasswordEditMode = false; // 🚀 NOUVEAU : Controle de droite (Mot de passe)

  passwordData = { currentPassword: '', newPassword: '', confirmPassword: '' };
  passwordSuccessMessage = '';
  passwordErrorMessage = '';

  assetsUrl = environment.assetsUrl;

  ngOnInit() {
    this.loadCurrentProfile();
  }

  toggleEditMode(mode: boolean) {
    this.isEditMode = mode;
    if (mode) {
      this.backupProfile = { ...this.profile };
    } else {
      this.profile = { ...this.backupProfile };
    }
    this.cdr.detectChanges();
  }

  // 🚀 NOUVELLE BASCULE POUR LE MOT DE PASSE INDÉPENDANT
  togglePasswordEditMode(mode: boolean) {
    this.isPasswordEditMode = mode;
    if (!mode) {
      // Si on annule, on vide la saisie
      this.passwordData = { currentPassword: '', newPassword: '', confirmPassword: '' };
    }
    this.cdr.detectChanges();
  }

    loadCurrentProfile() {
    const targetUrl = `${environment.apiUrl}/recruiter/profile/details`;
    const token = localStorage.getItem('token');

    fetch(targetUrl, {
      method: 'GET',
      headers: { 'Authorization': token ? `Bearer ${token}` : '' }
    })
    .then(async res => {
      if (res.ok) return res.json();
      throw new Error();
    })
    .then(data => {
      if (data) {
        this.profile.company_name = data.company_name || localStorage.getItem('name') || '';
        this.profile.phone = data.phone || '';
        this.profile.email = data.email || '';
        this.profile.address = data.address || '';
        this.profile.company_bio = data.company_bio || '';
        
        // 🚀 VÉRIFICATION ET ALIGNEMENT DU LOGO
        if (data.company_logo) {
          // Sécurité : Si l'ancienne chaîne contient déjà '/logos/', on extrait uniquement le nom du fichier
          const cleanFilename = data.company_logo.replace('/logos/', '');
          
          // 🌟 Recomposition propre vers le dossier exposé par votre serveur Express
          this.logoPreviewUrl = `${this.assetsUrl}/logos/${cleanFilename}`;
        }
        this.cdr.detectChanges();
      }
    })
    .catch(() => {
      this.profile.company_name = localStorage.getItem('name') || '';
      this.cdr.detectChanges();
    });
  }


  onFileSelected(event: any) {
    const file = event.target.files[0];
    if (file) {
      this.selectedFile = file;
      const reader = new FileReader();
      reader.onload = () => {
        this.logoPreviewUrl = reader.result as string;
        this.cdr.detectChanges();
      };
      reader.readAsDataURL(file);
    }
  }

  onSaveProfile(event: Event) {
    event.preventDefault();

    const targetUrl = `${environment.apiUrl}/recruiter/profile/update`;
    const token = localStorage.getItem('token');

    const formData = new FormData();
    formData.append('company_name', this.profile.company_name);
    formData.append('phone', this.profile.phone);
    formData.append('email', this.profile.email);
    formData.append('address', this.profile.address);
    formData.append('company_bio', this.profile.company_bio);

    if (this.selectedFile) {
      formData.append('logo', this.selectedFile);
    }

    fetch(targetUrl, {
      method: 'POST',
      headers: { 'Authorization': token ? `Bearer ${token}` : '' },
      body: formData
    })
    .then(async res => {
      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || "Impossible de sauvegarder votre profil.");
      }
      return res.json();
    })
    .then(resData => {
      localStorage.setItem('name', this.profile.company_name);
      this.successMessage = resData.message || "Les informations de votre profil et votre logo ont été mis à jour.";
      this.isEditMode = false;
      this.cdr.detectChanges();

      setTimeout(() => { this.successMessage = ''; this.cdr.detectChanges(); }, 3000);
    })
    .catch(err => alert(err.message));
  }

  onUpdatePassword(event: Event) {
    event.preventDefault();
    this.passwordSuccessMessage = '';
    this.passwordErrorMessage = '';

    if (this.passwordData.newPassword !== this.passwordData.confirmPassword) {
      this.passwordErrorMessage = "La confirmation ne correspond pas au nouveau mot de passe.";
      return;
    }

    if (this.passwordData.newPassword.length < 6) {
      this.passwordErrorMessage = "Le nouveau mot de passe doit contenir au moins 6 caractères.";
      return;
    }

    const targetUrl = `${environment.apiUrl}/recruiter/profile/change-password`;
    const token = localStorage.getItem('token');

    fetch(targetUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': token ? `Bearer ${token}` : ''
      },
      body: JSON.stringify({
        currentPassword: this.passwordData.currentPassword,
        newPassword: this.passwordData.newPassword
      })
    })
    .then(async res => {
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || "Erreur lors du changement de mot de passe.");
      return data;
    })
    .then(data => {
      this.passwordSuccessMessage = data.message || "Votre mot de passe a été modifié avec succès !";
      this.passwordData = { currentPassword: '', newPassword: '', confirmPassword: '' };
      this.isPasswordEditMode = false; // 🚀 Fermeture automatique après succès
      this.cdr.detectChanges();

      setTimeout(() => { this.passwordSuccessMessage = ''; this.cdr.detectChanges(); }, 4000);
    })
    .catch(err => {
      this.passwordErrorMessage = err.message;
      this.cdr.detectChanges();
    });
  }

  // ============================================================================
  // 🚀 AUTOCOMPLÉTION ADRESSE
  // ============================================================================

  onLocationInput(event: Event) {
    const searchTerm = (event.target as HTMLInputElement).value.toLowerCase();
    if (searchTerm.length > 0) {
      this.filteredLocations = (tunisianCities as { ville: string; cite: string }[]).filter(
        (loc: { ville: string; cite: string }) => 
          loc.ville.toLowerCase().startsWith(searchTerm) || 
          loc.cite.toLowerCase().startsWith(searchTerm)
      );
      this.showLocationSuggestions = this.filteredLocations.length > 0;
    } else {
      this.filteredLocations = [];
      this.showLocationSuggestions = false;
    }
  }

  selectLocation(location: { ville: string; cite: string }) {
    this.profile.address = `${location.ville}, ${location.cite}`;
    this.showLocationSuggestions = false;
  }

  onLocationBlur() {
    // Délai pour permettre le clic sur une suggestion avant de cacher la liste
    setTimeout(() => { this.showLocationSuggestions = false; }, 150);
  }
}
<div class="profile-container-compact">
  
  <div class="card-header-flex-compact">
    <div class="card-header-left">
      <h3><i class="bi bi-building-fill"></i> Gestion du Profil & Sécurité</h3>
    </div>
  </div>

  <!-- Alertes -->
  @if (successMessage) {
    <div class="alert-box-compact alert-success">{{ successMessage }}</div>
  }
  @if (passwordSuccessMessage) {
    <div class="alert-box-compact alert-success">{{ passwordSuccessMessage }}</div>
  }
  @if (passwordErrorMessage) {
    <div class="alert-box-compact alert-danger">{{ passwordErrorMessage }}</div>
  }

  <!-- DISPOSITION SPLIT -->
  <div class="profile-split-layout">
    
    <!-- ================= COLONNE GAUCHE : PROFIL ENTREPRISE ================= -->
    <div class="profile-panel-card">
      <form (ngSubmit)="onSaveProfile($event)">
        
        <div class="logo-section-compact">
          <div class="logo-preview-compact">
            @if (logoPreviewUrl) {
              <img [src]="logoPreviewUrl" alt="Logo">
            } @else {
              <i class="bi bi-building-fill" style="font-size: 24px; color: #cbd5e1;"></i>
            }
          </div>
          <div class="upload-actions-compact">
            <input type="file" id="logoInput" accept="image/*" (change)="onFileSelected($event)" style="display: none;">
            <button type="button" class="btn-secondary-upload-compact" [disabled]="!isEditMode" onclick="document.getElementById('logoInput').click()">
              <i class="bi bi-camera-fill"></i> Changer le logo
            </button>
          </div>
        </div>

        <div class="compact-form-grid">
          <div class="form-group-compact">
            <label>Raison sociale *</label>
            @if (isEditMode) {
              <input type="text" name="company_name" [(ngModel)]="profile.company_name" required>
            } @else {
              <div class="static-text-compact">{{ profile.company_name || 'Non renseigné' }}</div>
            }
          </div>

          <div class="form-group-compact">
            <label>Téléphone *</label>
            @if (isEditMode) {
              <input type="text" name="phone" [(ngModel)]="profile.phone" required>
            } @else {
              <div class="static-text-compact">{{ profile.phone || 'Non renseigné' }}</div>
            }
          </div>

          <div class="form-group-compact">
            <label>Email de contact *</label>
            @if (isEditMode) {
              <input type="email" name="email" [(ngModel)]="profile.email" required>
            } @else {
              <div class="static-text-compact">{{ profile.email || 'Non renseigné' }}</div>
            }
          </div>

          <div class="form-group-compact span-all">
            <label>Adresse du siège *</label>
            @if (isEditMode) {
              <input type="text" name="address" [(ngModel)]="profile.address" required>
            } @else {
              <div class="static-text-compact">{{ profile.address || 'Non renseigné' }}</div>
            }
          </div>

          <div class="form-group-compact span-all">
            <label>Présentation & Activités *</label>
            @if (isEditMode) {
              <textarea name="company_bio" [(ngModel)]="profile.company_bio" rows="3" required></textarea>
            } @else {
              <div class="static-text-compact textarea-view-compact">{{ profile.company_bio || 'Aucune description.' }}</div>
            }
          </div>
        </div>

        <div class="form-actions-compact">
          @if (!isEditMode) {
            <button type="button" class="btn-save-compact" (click)="toggleEditMode(true)">
              <i class="bi bi-pencil-square"></i> Modifier le profil
            </button>
          } @else {
            <button type="button" class="btn-cancel-compact" (click)="toggleEditMode(false)">Annuler</button>
            <button type="submit" class="btn-save-compact"><i class="bi bi-shield-check"></i> Enregistrer</button>
          }
        </div>
      </form>
    </div>

    <!-- ================= COLONNE DROITE : SÉCURITÉ DU COMPTE ================= -->
    <div class="profile-panel-card">
      <div class="panel-inner-title"><i class="bi bi-shield-lock-fill"></i> Sécurité du compte</div>
      
      <form (ngSubmit)="onUpdatePassword($event)">
        <div class="compact-form-grid vertical-stack">
          
          <!-- Mot de passe actuel -->
          <div class="form-group-compact">
            <label>Mot de passe actuel *</label>
            @if (isPasswordEditMode) {
              <input type="password" name="current_password" [(ngModel)]="passwordData.currentPassword" required placeholder="••••••••">
            } @else {
              <div class="static-text-compact text-muted-dots">••••••••••••</div>
            }
          </div>

          <!-- Nouveau Mot de passe -->
          <div class="form-group-compact">
            <label>Nouveau mot de passe *</label>
            @if (isPasswordEditMode) {
              <input type="password" name="new_password" [(ngModel)]="passwordData.newPassword" required placeholder="Min. 6 caractères">
            } @else {
              <div class="static-text-compact text-muted-dots">••••••••••••</div>
            }
          </div>

          <!-- Confirmation -->
          <div class="form-group-compact">
            <label>Confirmer le mot de passe *</label>
            @if (isPasswordEditMode) {
              <input type="password" name="confirm_password" [(ngModel)]="passwordData.confirmPassword" required placeholder="••••••••">
            } @else {
              <div class="static-text-compact text-muted-dots">••••••••••••</div>
            }
          </div>
        </div>

        <!-- 🛠️ ENCAPSULATION DES ACTIONS DU MOT DE PASSE SÉPARÉES -->
        <div class="form-actions-compact" style="margin-top: 24px;">
          @if (!isPasswordEditMode) {
            <!-- Mode Fermé : Bouton pour ouvrir -->
            <button type="button" class="btn-save-compact btn-dark-theme" (click)="togglePasswordEditMode(true)">
              <i class="bi bi-key-fill"></i> Modifier le mot de passe
            </button>
          } @else {
            <!-- Mode Ouvert : Duo Annuler / Enregistrer -->
            <button type="button" class="btn-cancel-compact" (click)="togglePasswordEditMode(false)">Annuler</button>
            <button type="submit" class="btn-save-compact btn-dark-theme"><i class="bi bi-shield-check"></i> Enregistrer</button>
          }
        </div>
      </form>
    </div>

  </div>
</div>
